import numpy as np

def select_item(current_index, remaining_capacity, weights, values, num_items, **kwargs):
    if current_index >= num_items:
        return 0
    w = float(weights[current_index])
    v = float(values[current_index])
    if w > remaining_capacity:
        return 0

    # 1. 计算已选择物品（假设之前返回1的物品已放入，这里用历史重量近似模拟）
    # 实际中无法直接获取已选列表，这里使用传入的历史信息或从剩余容量反推
    # 若没有历史，则基于总容量与剩余容量之差估计已用重量
    if 'total_capacity' in kwargs:
        total_cap = kwargs['total_capacity']
    else:
        total_cap = remaining_capacity + np.sum(weights[:current_index])  # 近似
    used_weight = total_cap - remaining_capacity
    # 已选物品数量近似（按平均重量估算）
    if current_index > 0:
        avg_w_selected = used_weight / max(current_index, 1)
    else:
        avg_w_selected = 0

    # 2. 空间填充模式：判断当前物品是否能与已选重量“互补”
    # 互补性：当前重量与平均已选重量的差异大，则有利于空间填充
    complement_score = abs(w - avg_w_selected) / max(w + avg_w_selected, 1e-6)

    # 3. 容量碎片填补：若剩余容量较小，且当前物品能填满大部分剩余，则强选
    fill_ratio_after = (remaining_capacity - w) / max(remaining_capacity, 1)
    fragment_score = 1.0 if fill_ratio_after <= 0.15 else 0.0

    # 4. 组合紧密度：计算当前物品与未来物品在重量上的互补性（近似）
    future_weights = weights[current_index+1:]
    if len(future_weights) > 0:
        # 找一个未来的重量，能与当前物品组合接近剩余容量或与之匹配
        future_pairs = future_weights + w
        match_future = np.any(np.abs(future_pairs - remaining_capacity) < 0.1 * remaining_capacity)
    else:
        match_future = False

    # 5. 随机规则切换：以概率决定使用哪种主导策略
    rand = np.random.random()
    if rand < 0.3:
        # 规则A：强调整合互补
        score = complement_score * 0.6 + v / max(w, 1e-6) * 0.2 + fragment_score * 0.2
        return 1 if score > 0.5 else 0
    elif rand < 0.6:
        # 规则B：强调填补碎片
        if fragment_score == 1:
            return 1
        else:
            # 若当前物品与未来某物品组合能接近剩余容量，则选
            if match_future:
                return 1
            else:
                return 0
    else:
        # 规则C：保守但考虑组合紧密度
        # 若当前物品重量较大且能紧密配合一个较小的未来物品，或当前物品很小且配合大物品
        if complement_score > 0.7 and w > 0:
            return 1
        else:
            return 0
